        }

        let pathsToTest = [
            root.appendingPathComponent(presentationRel),
            root.appendingPathComponent("Record-App").appendingPathComponent(theRecordRel),
        ]

        for dir in pathsToTest {
            guard fileManager.fileExists(atPath: dir.path) else {
                try #require(Bool(false), "Could not find \(dir.path) to test")
                return
            }
            try testDirectory(dir)
        }
    }

    private func testDirectory(_ directory: URL) throws {
        let fileManager = FileManager.default
        guard let enumerator = fileManager.enumerator(at: directory, includingPropertiesForKeys: nil) else {
            return
        }

        var violations: [String] = []
        let interpolationRegex = try NSRegularExpression(pattern: #"\\\([^\)]+\)"#)

        for case let fileURL as URL in enumerator where fileURL.pathExtension == "swift" {
            let content = try String(contentsOf: fileURL, encoding: .utf8)
            let lines = content.components(separatedBy: .newlines)

            for (index, line) in lines.enumerated() {
                let trimmed = line.trimmingCharacters(in: .whitespaces)
                if trimmed.contains("logger.") || trimmed.contains("Logger.") || trimmed.contains("os_log") {
                    let nsString = line as NSString
                    let matches = interpolationRegex.matches(
                        in: line,
                        range: NSRange(location: 0, length: nsString.length),
                    )

                    if !matches.isEmpty {
                        for match in matches {
                            let matchString = nsString.substring(with: match.range)
                            if !matchString.contains("privacy:") {
                                violations.append("\(fileURL.lastPathComponent):\(index + 1): \(trimmed)")
                            }
                        }
                    }
                }
            }
        }

        #expect(
            violations.isEmpty,
            "Found \(violations.count) log interpolations without explicit privacy labels in \(directory.lastPathComponent): \n\(violations.joined(separator: "\n"))",
        )
    }
}

