import Foundation
import Testing

/// Source-inspection tests verifying `TranscriptionSubAssembler` exposes a way to
/// connect a `ModelDownloadDelegate` to its download-capable engines, and that
/// `AppAssemblerBuilders.buildMenuBarVM` actually calls it with the real
/// `MenuBarViewModel` instance.
///
/// These tests inspect source because `AppAssembler`/`TranscriptionSubAssembler`
/// live in the `TheRecord` executable target (not a testable library, same
/// constraint documented in `AppAssemblerMCPWiringTests`). They act as
/// compile-time ratchets — if the wiring is removed, the test fails.
///
/// Context: #212 — `ModelDownloadDelegate` conformance existed on
/// `MenuBarViewModel` (via `MenuBarViewModelDownload.swift`) and `setDownloadDelegate`
/// setters existed on `ParakeetPlugin`/`WhisperKitPlugin`, but no assembler ever
/// called the setter, so download progress never reached the menu bar UI.
@Suite("AppAssemblerBuilders — ModelDownloadDelegate wiring (C2, #212)")
struct AppAssemblerDownloadDelegateWiringTests {
    private static func sourceFile(_ name: String) -> String {
        // #filePath → …/Record-App/Tests/Unit/Presentation/AppAssemblerDownloadDelegateWiringTests.swift
        // Go up 4 levels to the Record-App package root, then into Sources/TheRecord/.
        let thisFile = URL(fileURLWithPath: #filePath)
        let sourceURL = thisFile
            .deletingLastPathComponent() // Presentation/ → Unit/
            .deletingLastPathComponent() // Unit/ → Tests/
            .deletingLastPathComponent() // Tests/ → Record-App (package root)
            .deletingLastPathComponent() // Record-App → worktree root
            .appendingPathComponent("Sources/TheRecord/\(name)")
        return (try? String(contentsOf: sourceURL, encoding: .utf8)) ?? ""
    }

    private static let transcriptionSubAssemblerSource = sourceFile("TranscriptionSubAssembler.swift")
    private static let appAssemblerBuildersSource = sourceFile("AppAssemblerBuilders.swift")

    // AC1: TranscriptionSubAssembler.Built exposes a way to connect a delegate to
    // every download-capable engine it constructs (primary + cleanup).
    @Test("TranscriptionSubAssembler.Built exposes connectDownloadDelegate")
    func builtExposesConnectDownloadDelegate() {
        let message =
            "TranscriptionSubAssembler.Built must expose a connectDownloadDelegate hook so the composition "
                + "root can wire a ModelDownloadDelegate after the engines exist"
        #expect(Self.transcriptionSubAssemblerSource.contains("connectDownloadDelegate"), "\(message)")
    }

    // AC2: the hook actually calls setDownloadDelegate on the constructed engines,
    // not just a stub that discards the delegate.
    @Test("TranscriptionSubAssembler wires connectDownloadDelegate to setDownloadDelegate calls")
    func connectDownloadDelegateCallsSetDownloadDelegate() {
        #expect(
            Self.transcriptionSubAssemblerSource.contains("setDownloadDelegate(delegate)"),
            "connectDownloadDelegate must forward the delegate to the engines' setDownloadDelegate"
        )
    }

    // AC3: buildMenuBarVM actually calls connectDownloadDelegate with the real
    // MenuBarViewModel instance it just constructed — not merely declaring the hook
    // without ever invoking it.
    @Test("buildMenuBarVM connects the built MenuBarViewModel as the download delegate")
    func buildMenuBarVMConnectsMenuBarViewModelAsDownloadDelegate() {
        #expect(
            Self.appAssemblerBuildersSource.contains("connectDownloadDelegate(menuBarVM"),
            "buildMenuBarVM must call transcription.connectDownloadDelegate(menuBarVM) so real download progress reaches MenuBarViewModel.downloadProgress"
        )
    }
}

