import Testing
import Foundation
@testable import Business
import Domain
import AudioInfrastructure
import MLInfrastructure
import TestMocks

// MARK: - Factories

private func makeSession(id: RecordingID = RecordingID("session-001")) -> RecordingSession {
    RecordingSession(
        id: id,
        startedAt: Date(timeIntervalSince1970: 1_700_000_000),
        configuration: AudioConfiguration(),
    )
}

// MARK: - Suite

@Suite("StopAndTranscribeUseCase")
struct StopAndTranscribeUseCaseTests {

    // MARK: - Constructor / Injection

    /// Verifies the type is declared as `actor` with constructor injection of all
    /// five domain protocols. Fails to compile until StopAndTranscribeUseCase
    /// accepts sampleLoader and modelId — this is the intentional RED state.
    @Test
    func `is declared as actor and accepts AudioCaptureEngine, TranscriptionEngine, StorageEngine`() {
        _ = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )
    }

    // MARK: - Pipeline call sequencing

    @Test
    func `stopAndTranscribe(session:) calls audioCapture.stop()`() async throws {
        let mockCapture = MockAudioCaptureEngine()
        let useCase = StopAndTranscribeUseCase(
            audioCapture: mockCapture,
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        _ = try await useCase.stopAndTranscribe(session: makeSession())

        let called = await mockCapture.stopCalled
        #expect(called == true)
    }

    @Test
    func `stopAndTranscribe(session:) calls storage.saveRecording() with AudioFile from stop()`() async throws {
        let mockStorage = MockStorageEngine()
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: mockStorage,
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        _ = try await useCase.stopAndTranscribe(session: makeSession())

        let called = await mockStorage.saveRecordingCalled
        #expect(called == true)
    }

    @Test("execute throws and skips saveRecording if audio file is missing (TOCTOU fix)")
    func executeThrowsIfAudioFileIsMissing() async throws {
        let mockCapture = MockAudioCaptureEngine()
        let mockStorage = MockStorageEngine()

        let missingURL = URL(fileURLWithPath: NSTemporaryDirectory()).appendingPathComponent(UUID().uuidString)
        let missingFile = AudioFile(
            id: RecordingID("missing-file"),
            url: missingURL,
            recordedAt: Date(),
            duration: 1.0,
            fileSize: 1024,
            configuration: AudioConfiguration(),
            sampleCount: 16000,
        )
        await mockCapture.setMockAudioFile(missingFile)

        let useCase = StopAndTranscribeUseCase(
            audioCapture: mockCapture,
            transcription: MockTranscriptionEngine(),
            storage: mockStorage,
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        await #expect(throws: (any Error).self) {
            _ = try await useCase.stopAndTranscribe(session: makeSession())
        }

        let saveCalled = await mockStorage.saveRecordingCalled
        #expect(saveCalled == false, "Must check file presence transactionally BEFORE saving to storage")
    }

    @Test
    func `stopAndTranscribe(session:) calls transcription.transcribe() after saveRecording`() async throws {
        let mockTranscription = MockTranscriptionEngine()
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: mockTranscription,
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        _ = try await useCase.stopAndTranscribe(session: makeSession())

        let called = await mockTranscription.transcribeCalled
        #expect(called == true)
    }

    @Test
    func `stopAndTranscribe(session:) calls transcribe exactly once`() async throws {
        let mockTranscription = MockTranscriptionEngine()
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: mockTranscription,
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        _ = try await useCase.stopAndTranscribe(session: makeSession())

        let count = await mockTranscription.transcribeCallCount
        #expect(count == 1)
    }

    // MARK: - TranscriptionContext correctness

    @Test
    func `stopAndTranscribe(session:) builds TranscriptionResult with modelId from constructor`() async throws {
        // The use case must carry the injected modelId forward into the
        // TranscriptionResult it constructs — verifying modelId on the result
        // proves the constructor parameter is wired through rather than hardcoded.
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        let result = try await useCase.stopAndTranscribe(session: makeSession())

        #expect(result.transcription.modelId == ModelID("test-model"))
    }

    @Test
    func `stopAndTranscribe(session:) passes isFinalChunk: true — transcription result contains segments`(
    ) async throws {
        // isFinalChunk: true is not directly observable from outside via the mock,
        // but the call to transcribe (which requires isFinalChunk: true per the spec)
        // must produce at least one segment in the result.
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        let result = try await useCase.stopAndTranscribe(session: makeSession())

        #expect(result.transcription.segments.isEmpty == false)
    }

    // MARK: - Return value shape

    @Test
    func `stopAndTranscribe(session:) returns TranscribedRecording whose recording id matches AudioFile`() async throws {
        // MockAudioCaptureEngine.stop() returns AudioFile(id: generated, …).
        // MockStorageEngine.saveRecording() stores metadata using file.id.
        // Verifying the id proves storage.saveRecording was called with the
        // AudioFile that audioCapture.stop() returned — not some other value.
        //
        // Note: In this isolated unit test, we're not calling audioCapture.start()
        // (that's StartRecordingUseCase's job), so the MockAudioCaptureEngine
        // generates a fresh ID on stop(). In integration (StartRecordingUseCase →
        // StopAndTranscribeUseCase), INV-001 ensures AudioFile.id == RecordingSession.id.
        let mockStorage = MockStorageEngine()
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: mockStorage,
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        let result = try await useCase.stopAndTranscribe(session: makeSession())

        // Verify that the recording ID returned from the use case matches
        // what the mock storage recorded (not a mutation or different value).
        let storedRecording = try await mockStorage.getRecording(id: result.recording.metadata.id)
        #expect(storedRecording.metadata.id == result.recording.metadata.id)
    }

    @Test
    func `stopAndTranscribe(session:) builds TranscriptionResult with non-empty fullText`() async throws {
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        let result = try await useCase.stopAndTranscribe(session: makeSession())

        #expect(result.transcription.fullText.isEmpty == false)
    }

    // MARK: - Error propagation

    @Test
    func `stopAndTranscribe(session:) propagates error thrown by transcription.transcribe — not swallowed`(
    ) async throws {
        let mockTranscription = MockTranscriptionEngine()
        await mockTranscription.setErrorToThrow(RecordingError.sessionExpired)

        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: mockTranscription,
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        await #expect(throws: (any Error).self) {
            _ = try await useCase.stopAndTranscribe(session: makeSession())
        }
    }

    // MARK: - AudioSampleLoader injection (NEW — RED until source is refactored)

    /// Verifies that execute() delegates sample loading to the injected
    /// AudioSampleLoader rather than calling a private loadSamples method.
    /// Fails until StopAndTranscribeUseCase calls sampleLoader.loadSamples(from:).
    @Test("execute calls injected sampleLoader.loadSamples(from:)")
    func executeCallsInjectedSampleLoader() async throws {
        let mockLoader = MockAudioSampleLoader()
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: mockLoader,
            modelId: ModelID("test-model"),
        )

        _ = try await useCase.stopAndTranscribe(session: makeSession())

        let called = await mockLoader.loadSamplesCalled
        #expect(called == true)
    }

    /// Verifies the injected sampleLoader is called exactly once per execute call.
    @Test("execute calls sampleLoader.loadSamples exactly once")
    func executeCallsSampleLoaderExactlyOnce() async throws {
        let mockLoader = MockAudioSampleLoader()
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: mockLoader,
            modelId: ModelID("test-model"),
        )

        _ = try await useCase.stopAndTranscribe(session: makeSession())

        let count = await mockLoader.loadSamplesCallCount
        #expect(count == 1)
    }

    // MARK: - modelId parameter injection (NEW — RED until source is refactored)

    /// Verifies that a custom modelId injected at construction time propagates
    /// into the TranscriptionResult.modelId field. Fails until the constructor
    /// accepts a modelId parameter and wires it into the context/result.
    @Test("injected modelId flows through to TranscriptionResult.modelId")
    func injectedModelIdFlowsThroughToResult() async throws {
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("openai_whisper-base"),
        )

        let result = try await useCase.stopAndTranscribe(session: makeSession())

        #expect(result.transcription.modelId == ModelID("openai_whisper-base"))
    }

    // MARK: - passType (NEW — RED until source sets passType: .live)

    /// Verifies that the TranscriptionResult produced by execute() carries
    /// passType: .live, identifying this as the real-time transcription pass.
    /// Fails until StopAndTranscribeUseCase constructs TranscriptionResult with
    /// passType: .live.
    @Test("execute returns TranscriptionResult with passType .live")
    func transcriptionResultPassTypeIsLive() async throws {
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        let result = try await useCase.stopAndTranscribe(session: makeSession())

        #expect(result.transcription.passType == .live)
    }

    // MARK: - Persistence (Codex adversarial finding 2)

    /// Verifies that execute() persists the live transcription result to storage
    /// via updateTranscript so it survives app restart and is searchable.
    @Test("execute persists live transcript via storage.updateTranscript")
    func executePersistsTranscriptViaStorage() async throws {
        let mockStorage = MockStorageEngine()
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: mockStorage,
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        _ = try await useCase.stopAndTranscribe(session: makeSession())

        let called = await mockStorage.updateTranscriptCalled
        #expect(called == true)
    }

    // MARK: - BM-020 getComputeUnit wiring

    /// Verifies that the TranscriptionResult produced by stopAndTranscribe(session:)
    /// carries the compute unit reported by the engine rather than the hardcoded
    /// `.unknown` sentinel. MockTranscriptionEngine.getComputeUnit() returns
    /// `.cpuAndNeuralEngine`, so a correctly wired result must match that value.
    @Test("computeUnit from engine is wired through to TranscriptionResult (BM-020)")
    func computeUnitFromEngineFlowsThroughToResult() async throws {
        // Arrange: MockTranscriptionEngine.getComputeUnit() returns .cpuAndNeuralEngine
        let mockTranscription = MockTranscriptionEngine()
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: mockTranscription,
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        // Act
        let result = try await useCase.stopAndTranscribe(session: makeSession())

        // Assert: real compute unit flows through, not the .unknown sentinel
        #expect(
            result.transcription.computeUnit == .cpuAndNeuralEngine,
            "computeUnit must reflect what the engine reports, not be hardcoded to .unknown",
        )
    }

    // MARK: - Model readiness gate (BM-033)

    //
    // StopAndTranscribeUseCase must gate transcription on engine readiness,
    // mirroring the fix applied to StreamingTranscriptionUseCase in TASK-033.
    //
    // RED baseline: the use case currently calls transcription.transcribe()
    // without ever consulting isReady() or calling loadModel(). These three
    // tests are intentionally RED until the gate is added.

    /// AC-A: Engine starts NOT ready, loadModel succeeds → lazy-load path
    /// fires and transcribe IS called.
    ///
    /// RED: the current source never calls loadModel(). loadModelCalled stays
    /// false → #expect(loadModelCalled == true) fails.
    @Test("engine not ready: calls loadModel then transcribes (lazy-load path, AC-A)")
    func engineNotReadyCallsLoadModelThenTranscribes() async throws {
        // Precondition — engine must start not-ready (default state)
        let mockTranscription = MockTranscriptionEngine()
        let initiallyReady = await mockTranscription.isReady()
        #expect(initiallyReady == false, "Precondition: MockTranscriptionEngine must start not-ready")

        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: mockTranscription,
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        // Act — should succeed: lazy-load fires, then transcribe succeeds
        _ = try await useCase.stopAndTranscribe(session: makeSession())

        // Assert — the readiness gate must have called loadModel(), then transcribe()
        let loadCalled = await mockTranscription.loadModelCalled
        let transcribeCalled = await mockTranscription.transcribeCalled
        #expect(
            loadCalled == true,
            "use case must call loadModel() when engine is not ready (lazy-load gate)",
        )
        #expect(
            transcribeCalled == true,
            "transcribe() must be called after loadModel() succeeds",
        )
    }

    /// AC-B: Engine NOT ready and loadModel throws → transcribe is NEVER
    /// called and the error propagates to the caller.
    ///
    /// RED: the current source calls transcribe() directly. transcribeCalled
    /// becomes true (before the throw) → #expect(transcribeCalled == false) fails.
    @Test("engine not ready: loadModel throws → transcribe never called, error propagates (AC-B)")
    func engineNotReadyLoadModelThrowsAbortsPipeline() async throws {
        // Arrange — engine starts NOT ready; errorToThrow makes loadModel throw
        let mockTranscription = MockTranscriptionEngine()
        struct ModelLoadFailure: Error {}
        await mockTranscription.setErrorToThrow(ModelLoadFailure())

        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: mockTranscription,
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        // Act — execute() must propagate the loadModel error
        await #expect(throws: (any Error).self) {
            _ = try await useCase.stopAndTranscribe(session: makeSession())
        }

        // Assert — transcribe() must never have been called
        let transcribeCalled = await mockTranscription.transcribeCalled
        #expect(
            transcribeCalled == false,
            "transcribe() must not be called when loadModel throws — gate must abort the pipeline",
        )
    }

    /// AC-C: Engine already ready → loadModel is NOT called and transcribe
    /// fires immediately.
    ///
    /// Currently PASSES (the gate is absent, so loadModel is never called and
    /// transcribe is called unconditionally). Serves as a regression guard to
    /// ensure the gate's fast-path stays correct after GREEN.
    @Test("engine already ready: loadModel skipped, transcribe fires immediately (AC-C)")
    func engineAlreadyReadySkipsLoadModel() async throws {
        // Arrange — mark engine ready before execute()
        let mockTranscription = MockTranscriptionEngine()
        await mockTranscription.setReady(true)
        let isReady = await mockTranscription.isReady()
        #expect(isReady == true, "Precondition: engine must be ready before execute()")

        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: mockTranscription,
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        // Act
        _ = try await useCase.stopAndTranscribe(session: makeSession())

        // Assert — loadModel must NOT be called; transcribe must be called
        let loadCalled = await mockTranscription.loadModelCalled
        let transcribeCalled = await mockTranscription.transcribeCalled
        #expect(
            loadCalled == false,
            "loadModel() must not be called when engine is already ready",
        )
        #expect(
            transcribeCalled == true,
            "transcribe() must be called when engine is already ready",
        )
    }

    // MARK: - Inference Telemetry (Epic 3.5)

    @Test("records inference metrics to telemetry after transcription")
    func recordsInferenceTelemetry() async throws {
        let telemetry = InferenceTelemetry()
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
            telemetry: telemetry,
        )

        _ = try await useCase.stopAndTranscribe(session: makeSession())

        let recent = await telemetry.recentMetrics(limit: 1)
        #expect(recent.count == 1, "One telemetry entry must be recorded per transcription")
        #expect(recent[0].modelId == ModelID("test-model"))
        #expect(recent[0].sampleCount > 0)
        #expect(recent[0].inferenceDuration >= 0)
    }

    @Test("telemetry is optional — nil telemetry does not crash")
    func nilTelemetryDoesNotCrash() async throws {
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        let result = try await useCase.stopAndTranscribe(session: makeSession())
        #expect(!result.transcription.fullText.isEmpty)
    }

    // MARK: - WAV Preservation on Persistence Failure (F4/#193)

    @Test("WAV file is preserved on disk when saveRecording throws (retryable)")
    func wavFileIsPreservedWhenSaveRecordingThrows() async throws {
        let mockCapture = MockAudioCaptureEngine()
        let mockStorage = MockStorageEngine()

        let tempURL = URL(fileURLWithPath: NSTemporaryDirectory()).appendingPathComponent(UUID().uuidString + ".wav")
        try Data("dummy".utf8).write(to: tempURL)
        defer { try? FileManager.default.removeItem(at: tempURL) }

        let tempFile = AudioFile(
            id: RecordingID("temp-file"),
            url: tempURL,
            recordedAt: Date(),
            duration: 1.0,
            fileSize: 1024,
            configuration: AudioConfiguration(),
            sampleCount: 16000,
        )
        await mockCapture.setMockAudioFile(tempFile)

        struct TransientStorageFailure: Error {}
        await mockStorage.setErrorToThrow(TransientStorageFailure())

        let useCase = StopAndTranscribeUseCase(
            audioCapture: mockCapture,
            transcription: MockTranscriptionEngine(),
            storage: mockStorage,
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        await #expect(throws: (any Error).self) {
            _ = try await useCase.stopAndTranscribe(session: makeSession())
        }

        #expect(
            FileManager.default.fileExists(atPath: tempURL.path) == true,
            "WAV file must be preserved on disk when saveRecording throws — storage failure is retryable",
        )
    }

    @Test("forceStop deletes returned .wav file")
    func forceStopDeletesReturnedWavFile() async throws {
        let mockCapture = MockAudioCaptureEngine()

        let tempURL = URL(fileURLWithPath: NSTemporaryDirectory()).appendingPathComponent(UUID().uuidString + ".wav")
        try Data("dummy".utf8).write(to: tempURL)
        defer { try? FileManager.default.removeItem(at: tempURL) }

        let tempFile = AudioFile(
            id: RecordingID("temp-file"),
            url: tempURL,
            recordedAt: Date(),
            duration: 1.0,
            fileSize: 1024,
            configuration: AudioConfiguration(),
            sampleCount: 16000,
        )
        await mockCapture.setMockAudioFile(tempFile)

        let useCase = StopAndTranscribeUseCase(
            audioCapture: mockCapture,
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        await useCase.forceStop()

        #expect(
            FileManager.default.fileExists(atPath: tempURL.path) == false,
            "forceStop must delete the generated .wav file",
        )
    }

    // MARK: - Crash Resilience — WhisperKit/MLX Recovery (#116)
    //
    // These tests are intentionally RED until the GREEN phase implements:
    //   1. RecordingStatus.needsRetranscription in Domain (new enum case)
    //   2. RecordingWriteRepository.markNeedsRetranscription(id:audioURL:) protocol method
    //   3. RecordingReadRepository.listNeedsRetranscription() protocol method
    //   4. StopAndTranscribeUseCase recovery path: on transcription failure,
    //      call storage.markNeedsRetranscription() instead of propagating raw error
    //   5. RecoverPendingSessionsUseCase.callAsFunction() surfaces .needsRetranscription rows
    //   6. Audio integrity check before marking recoverable

    /// AC-1 (REQ-B1, #116): When transcription throws, the WAV file on disk
    /// must be preserved so the session can be retried. The use case must NOT
    /// delete the file on transcription failure.
    ///
    /// RED: the current use case propagates the error without ensuring the WAV
    /// is preserved; no test verifies this invariant for the transcription path.
    @Test("transcription failure preserves WAV file on disk for retry (AC-1, #116)")
    func transcriptionFailurePreservesWavFile() async throws {
        let mockCapture = MockAudioCaptureEngine()
        let mockTranscription = MockTranscriptionEngine()
        let mockStorage = MockStorageEngine()

        // Write a minimal WAV file so the TOCTOU file-handle check passes
        let wavURL = URL(fileURLWithPath: NSTemporaryDirectory())
            .appendingPathComponent(UUID().uuidString + ".wav")
        try Data("RIFF\0\0\0\0WAVEfmt ".utf8).write(to: wavURL)
        defer { try? FileManager.default.removeItem(at: wavURL) }

        let wavFile = AudioFile(
            id: RecordingID("session-crash-001"),
            url: wavURL,
            recordedAt: Date(),
            duration: 5.0,
            fileSize: Int64(wavURL.resourceValues(forKeys: [.fileSizeKey]).fileSize ?? 1024),
            configuration: AudioConfiguration(),
            sampleCount: 80000,
        )
        await mockCapture.setMockAudioFile(wavFile)

        // Make transcription throw — simulates WhisperKit/MLX crash
        struct WhisperKitCrash: Error {}
        await mockTranscription.setErrorToThrow(WhisperKitCrash())
        // Engine starts not-ready; errorToThrow fires on loadModel, skipping transcribe.
        // Force ready so the error fires on transcribe() instead.
        await mockTranscription.setReady(true)
        // Now re-set the error so transcribe() throws
        await mockTranscription.setErrorToThrow(WhisperKitCrash())

        let useCase = StopAndTranscribeUseCase(
            audioCapture: mockCapture,
            transcription: mockTranscription,
            storage: mockStorage,
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        // Act — must throw (transcription failed)
        await #expect(throws: (any Error).self) {
            _ = try await useCase.stopAndTranscribe(session: makeSession(id: RecordingID("session-crash-001")))
        }

        // Assert — WAV file must still exist on disk for retry
        #expect(
            FileManager.default.fileExists(atPath: wavURL.path) == true,
            "WAV file must be preserved on disk when transcription throws (retryable crash recovery)"
        )
    }

    /// AC-2 (REQ-B1, #116): When transcription throws, the use case must mark the
    /// stored recording as .needsRetranscription via storage.markNeedsRetranscription().
    ///
    /// RED: RecordingStatus.needsRetranscription does not exist in Domain and
    /// MockStorageEngine has no markNeedsRetranscriptionCalled tracking property.
    /// This test will fail to compile until both are added.
    @Test("transcription failure marks recording as .needsRetranscription (AC-2, #116)")
    func transcriptionFailureMarksRecordingNeedsRetranscription() async throws {
        let mockCapture = MockAudioCaptureEngine()
        let mockTranscription = MockTranscriptionEngine()
        let mockStorage = MockStorageEngine()

        let wavURL = URL(fileURLWithPath: NSTemporaryDirectory())
            .appendingPathComponent(UUID().uuidString + ".wav")
        try Data("RIFF\0\0\0\0WAVEfmt ".utf8).write(to: wavURL)
        defer { try? FileManager.default.removeItem(at: wavURL) }

        let wavFile = AudioFile(
            id: RecordingID("session-crash-002"),
            url: wavURL,
            recordedAt: Date(),
            duration: 3.0,
            fileSize: 2048,
            configuration: AudioConfiguration(),
            sampleCount: 48000,
        )
        await mockCapture.setMockAudioFile(wavFile)
        await mockTranscription.setReady(true)

        struct MLXCrash: Error {}
        await mockTranscription.setErrorToThrow(MLXCrash())

        let useCase = StopAndTranscribeUseCase(
            audioCapture: mockCapture,
            transcription: mockTranscription,
            storage: mockStorage,
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        await #expect(throws: (any Error).self) {
            _ = try await useCase.stopAndTranscribe(session: makeSession(id: RecordingID("session-crash-002")))
        }

        // RED: MockStorageEngine.markNeedsRetranscriptionCalled does not exist yet.
        // This line will produce a compile error until the GREEN phase adds:
        //   - RecordingStatus.needsRetranscription (Domain)
        //   - RecordingWriteRepository.markNeedsRetranscription(id:audioURL:) (Domain)
        //   - MockStorageEngine.markNeedsRetranscriptionCalled (TestMocks)
        let marked = await mockStorage.markNeedsRetranscriptionCalled
        #expect(
            marked == true,
            "storage.markNeedsRetranscription() must be called when transcription throws"
        )
    }

    /// AC-3 (REQ-B1, #116): RecoverPendingSessionsUseCase must surface recordings
    /// with status .needsRetranscription on next launch, not just crash-mid-capture.
    ///
    /// RED: RecordingReadRepository.listNeedsRetranscription() does not exist yet.
    /// Compile error until added.
    @Test("RecoverPendingSessionsUseCase returns .needsRetranscription sessions (AC-3, #116)")
    func recoverPendingSessionsPicksUpNeedsRetranscription() async throws {
        let mockStorage = MockStorageEngine()
        let crashedID = RecordingID("session-crashed-transcription")

        // Seed a recording that was saved but transcription crashed
        // RED: seedNeedsRetranscription(id:audioURL:) does not exist on MockStorageEngine yet.
        // This line fails to compile until MockStorageEngine gains this method.
        await mockStorage.seedNeedsRetranscription(id: crashedID, audioURL: URL(fileURLWithPath: "/tmp/dummy.wav"))

        let useCase = RecoverPendingSessionsUseCase(storage: mockStorage)
        let recovered = try await useCase()

        #expect(
            recovered.contains(crashedID),
            "RecoverPendingSessionsUseCase must surface .needsRetranscription sessions (#116)"
        )
    }

    /// AC-4 (REQ-B1, #116): Before marking a crashed session as recoverable, the
    /// use case must verify the WAV file has a valid header and non-zero size.
    /// An empty or truncated WAV must NOT be marked as .needsRetranscription.
    ///
    /// RED: no integrity check exists in the current code path.
    /// The mock storage must expose verifyAudioIntegrityCalled; fails to compile
    /// until MockStorageEngine.verifyAudioIntegrityCalled is added and the use
    /// case calls it before markNeedsRetranscription.
    @Test("audio integrity verified (WAV header + size > 0) before marking recoverable (AC-4, #116)")
    func audioIntegrityVerifiedBeforeMarkingRecoverable() async throws {
        let mockCapture = MockAudioCaptureEngine()
        let mockTranscription = MockTranscriptionEngine()
        let mockStorage = MockStorageEngine()

        // Write an empty (zero-byte) WAV — integrity check must reject it
        let emptyWavURL = URL(fileURLWithPath: NSTemporaryDirectory())
            .appendingPathComponent(UUID().uuidString + ".wav")
        try Data().write(to: emptyWavURL)
        defer { try? FileManager.default.removeItem(at: emptyWavURL) }

        let emptyFile = AudioFile(
            id: RecordingID("session-empty-wav"),
            url: emptyWavURL,
            recordedAt: Date(),
            duration: 0.0,
            fileSize: 0,
            configuration: AudioConfiguration(),
            sampleCount: 0,
        )
        await mockCapture.setMockAudioFile(emptyFile)
        await mockTranscription.setReady(true)

        struct TranscriptionError: Error {}
        await mockTranscription.setErrorToThrow(TranscriptionError())

        let useCase = StopAndTranscribeUseCase(
            audioCapture: mockCapture,
            transcription: mockTranscription,
            storage: mockStorage,
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        await #expect(throws: (any Error).self) {
            _ = try await useCase.stopAndTranscribe(session: makeSession(id: RecordingID("session-empty-wav")))
        }

        // RED: when fileSize == 0, markNeedsRetranscription must NOT be called —
        // the file is unrecoverable. This fails until the integrity gate is implemented.
        let marked = await mockStorage.markNeedsRetranscriptionCalled
        #expect(
            marked == false,
            "markNeedsRetranscription must NOT be called for zero-byte WAV — unrecoverable file"
        )
    }
}

import Foundation
import Testing

/// Source-inspection tests verifying `TranscriptionSubAssembler` exposes a way to
/// connect a `ModelDownloadDelegate` to its download-capable engines, and that
/// `AppAssemblerBuilders.buildMenuBarVM` actually calls it with the real
/// `MenuBarViewModel` instance.
///
/// These tests inspect source because `AppAssembler`/`TranscriptionSubAssembler`
/// live in the `TheRecord` executable target (not a testable library, same
/// constraint documented in `AppAssemblerMCPWiringTests`). They act as
/// compile-time ratchets — if the wiring is removed, the test fails.
///
/// Context: #212 — `ModelDownloadDelegate` conformance existed on
/// `MenuBarViewModel` (via `MenuBarViewModelDownload.swift`) and `setDownloadDelegate`
/// setters existed on `ParakeetPlugin`/`WhisperKitPlugin`, but no assembler ever
/// called the setter, so download progress never reached the menu bar UI.
@Suite("AppAssemblerBuilders — ModelDownloadDelegate wiring (C2, #212)")
struct AppAssemblerDownloadDelegateWiringTests {
    private static func sourceFile(_ name: String) -> String {
        // #filePath → …/Record-App/Tests/Unit/Presentation/AppAssemblerDownloadDelegateWiringTests.swift
        // Go up 4 levels to the Record-App package root, then into Sources/TheRecord/.
        let thisFile = URL(fileURLWithPath: #filePath)
        let sourceURL = thisFile
            .deletingLastPathComponent() // Presentation/ → Unit/
            .deletingLastPathComponent() // Unit/ → Tests/
            .deletingLastPathComponent() // Tests/ → Record-App (package root)
            .deletingLastPathComponent() // Record-App → worktree root
            .appendingPathComponent("Sources/TheRecord/\(name)")
        return (try? String(contentsOf: sourceURL, encoding: .utf8)) ?? ""
    }

    private static let transcriptionSubAssemblerSource = sourceFile("TranscriptionSubAssembler.swift")
    private static let appAssemblerBuildersSource = sourceFile("AppAssemblerBuilders.swift")

    // AC1: TranscriptionSubAssembler.Built exposes a way to connect a delegate to
    // every download-capable engine it constructs (primary + cleanup).
    @Test("TranscriptionSubAssembler.Built exposes connectDownloadDelegate")
    func builtExposesConnectDownloadDelegate() {
        let message =
            "TranscriptionSubAssembler.Built must expose a connectDownloadDelegate hook so the composition "
                + "root can wire a ModelDownloadDelegate after the engines exist"
        #expect(Self.transcriptionSubAssemblerSource.contains("connectDownloadDelegate"), "\(message)")
    }

    // AC2: the hook actually calls setDownloadDelegate on the constructed engines,
    // not just a stub that discards the delegate.
    @Test("TranscriptionSubAssembler wires connectDownloadDelegate to setDownloadDelegate calls")
    func connectDownloadDelegateCallsSetDownloadDelegate() {
        #expect(
            Self.transcriptionSubAssemblerSource.contains("setDownloadDelegate(delegate)"),
            "connectDownloadDelegate must forward the delegate to the engines' setDownloadDelegate"
        )
    }

    // AC3: buildMenuBarVM actually calls connectDownloadDelegate with the real
    // MenuBarViewModel instance it just constructed — not merely declaring the hook
    // without ever invoking it.
    @Test("buildMenuBarVM connects the built MenuBarViewModel as the download delegate")
    func buildMenuBarVMConnectsMenuBarViewModelAsDownloadDelegate() {
        let message =
            "buildMenuBarVM must call transcription.connectDownloadDelegate(menuBarVM) so real download "
                + "progress reaches MenuBarViewModel.downloadProgress"
        #expect(Self.appAssemblerBuildersSource.contains("connectDownloadDelegate(menuBarVM"), "\(message)")
    }
}

import Testing
import Foundation

@Suite("OSLog Privacy - Presentation & TheRecord Layer")
struct OSLogPrivacyPresentationTests {

    @Test("Presentation and App layer log interpolations must have privacy labels")
    func presentationAndAppLayerOSLogPrivacyCompliant() throws {
        let fileManager = FileManager.default
        let projectRoot = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()

        var root = projectRoot
        let presentationRel = "Record-Presentation/Sources/Presentation"
        let theRecordRel = "Sources/TheRecord"

        if !fileManager.fileExists(atPath: root.appendingPathComponent(presentationRel).path) {
            root = root.deletingLastPathComponent()
        }

        let pathsToTest = [
            root.appendingPathComponent(presentationRel),
            root.appendingPathComponent("Record-App").appendingPathComponent(theRecordRel),
        ]

        for dir in pathsToTest {
            guard fileManager.fileExists(atPath: dir.path) else {
                try #require(Bool(false), "Could not find \(dir.path) to test")
                return
            }
            try testDirectory(dir)
        }
    }

    private func testDirectory(_ directory: URL) throws {
        let fileManager = FileManager.default
        guard let enumerator = fileManager.enumerator(at: directory, includingPropertiesForKeys: nil) else {
            return
        }

        var violations: [String] = []
        let interpolationRegex = try NSRegularExpression(pattern: #"\\\([^\)]+\)"#)

        for case let fileURL as URL in enumerator where fileURL.pathExtension == "swift" {
            let content = try String(contentsOf: fileURL, encoding: .utf8)
            let lines = content.components(separatedBy: .newlines)

            for (index, line) in lines.enumerated() {
                let trimmed = line.trimmingCharacters(in: .whitespaces)
                if trimmed.contains("logger.") || trimmed.contains("Logger.") || trimmed.contains("os_log") {
                    let nsString = line as NSString
                    let matches = interpolationRegex.matches(
                        in: line,
                        range: NSRange(location: 0, length: nsString.length),
                    )

                    if !matches.isEmpty {
                        for match in matches {
                            let matchString = nsString.substring(with: match.range)
                            if !matchString.contains("privacy:") {
                                violations.append("\(fileURL.lastPathComponent):\(index + 1): \(trimmed)")
                            }
                        }
                    }
                }
            }
        }

        let message =
            "Found \(violations.count) log interpolations without explicit privacy labels in "
                + "\(directory.lastPathComponent): \n\(violations.joined(separator: "\n"))"
        #expect(violations.isEmpty, "\(message)")
    }
}

import Foundation
import Testing

@Suite("OSLog Privacy Infrastructure Layer Tests")
struct OSLogPrivacyInfrastructureTests {

    @Test func infrastructureLayerOSLogPrivacyCompliant() throws {
        let fileManager = FileManager.default
        // The tests are executed from the Record-App directory. We can get the current directory path.
        let rootURL = URL(fileURLWithPath: #file)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
        let sourcesURL = rootURL.appendingPathComponent("Record-Foundation/Sources/Infrastructure")

        let enumerator = fileManager.enumerator(at: sourcesURL, includingPropertiesForKeys: nil)
        var violations = 0

        // This regex tries to find `\(` followed by any characters EXCEPT `, privacy:` up to a `)`
        // However, a simpler approach for the test is to look for Logger. or os_log calls that have string
        // interpolations
        // A simpler regex to match `\(something)` that doesn't end with `, privacy: something)`
        // Wait, the specification provides the regex: #"\\(.+(?!, privacy:)\\)"#
        // Let's implement it carefully.

        let regex = try NSRegularExpression(pattern: #"\\\\(.+(?!, privacy:)\\)"#, options: [])

        while let fileURL = enumerator?.nextObject() as? URL {
            if fileURL.pathExtension == "swift" {
                let content = try String(contentsOf: fileURL, encoding: .utf8)
                let lines = content.components(separatedBy: .newlines)

                for (index, line) in lines.enumerated() {
                    let lineNumber = index + 1

                    if line.contains("Logger(") || line.contains("Logger.") || line.contains("os_log") || line
                        .contains("logger.") || line.contains(".debug(") || line.contains(".info(") || line
                        .contains(".error(") || line.contains(".warning(") || line.contains(".trace(") || line
                        .contains(".notice(") || line.contains(".critical(") || line.contains(".fault(") {
                        // Use the regex to find violations
                        let range = NSRange(location: 0, length: line.utf16.count)
                        if regex.firstMatch(in: line, options: [], range: range) != nil {
                            print("\(fileURL.lastPathComponent):\(lineNumber) - Missing privacy label")
                            violations += 1
                        }
                    }
                }
            }
        }

        let message =
            "Found \(violations) OSLog privacy violations in Infrastructure layer. "
                + "All string interpolations in log messages must specify a privacy level."
        #expect(violations == 0, "\(message)")
    }
}

