@testable import Business
import Domain
import AudioInfrastructure
import MLInfrastructure
import TestMocks

// MARK: - Suite

@Suite("StopAndTranscribeUseCase")
struct StopAndTranscribeUseCaseTests {

    // MARK: - Constructor / Injection

    /// Verifies the type is declared as `actor` with constructor injection of all
    /// five domain protocols. Fails to compile until StopAndTranscribeUseCase
    /// accepts sampleLoader and modelId — this is the intentional RED state.
    @Test
    func `is declared as actor and accepts AudioCaptureEngine, TranscriptionEngine, StorageEngine`() {
        _ = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )
    }

    // MARK: - Pipeline call sequencing

    @Test
    func `stopAndTranscribe(session:) calls audioCapture.stop()`() async throws {
        let mockCapture = MockAudioCaptureEngine()
        let useCase = StopAndTranscribeUseCase(
            audioCapture: mockCapture,
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        _ = try await useCase.stopAndTranscribe(session: makeSession())

        let called = await mockCapture.stopCalled
        #expect(called == true)
    }

    @Test
    func `stopAndTranscribe(session:) calls storage.saveRecording() with AudioFile from stop()`() async throws {
        let mockStorage = MockStorageEngine()
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: mockStorage,
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        _ = try await useCase.stopAndTranscribe(session: makeSession())

        let called = await mockStorage.saveRecordingCalled
        #expect(called == true)
    }

    @Test("execute throws and skips saveRecording if audio file is missing (TOCTOU fix)")
    func executeThrowsIfAudioFileIsMissing() async throws {
        let mockCapture = MockAudioCaptureEngine()
        let mockStorage = MockStorageEngine()

        let missingURL = URL(fileURLWithPath: NSTemporaryDirectory()).appendingPathComponent(UUID().uuidString)
        let missingFile = AudioFile(
            id: RecordingID("missing-file"),
            url: missingURL,
            recordedAt: Date(),
            duration: 1.0,
            fileSize: 1024,
            configuration: AudioConfiguration(),
            sampleCount: 16000,
        )
        await mockCapture.setMockAudioFile(missingFile)

        let useCase = StopAndTranscribeUseCase(
            audioCapture: mockCapture,
            transcription: MockTranscriptionEngine(),
            storage: mockStorage,
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        await #expect(throws: (any Error).self) {
            _ = try await useCase.stopAndTranscribe(session: makeSession())
        }

        let saveCalled = await mockStorage.saveRecordingCalled
        #expect(saveCalled == false, "Must check file presence transactionally BEFORE saving to storage")
    }

    @Test
    func `stopAndTranscribe(session:) calls transcription.transcribe() after saveRecording`() async throws {
        let mockTranscription = MockTranscriptionEngine()
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: mockTranscription,
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        _ = try await useCase.stopAndTranscribe(session: makeSession())

        let called = await mockTranscription.transcribeCalled
        #expect(called == true)
    }

    @Test
    func `stopAndTranscribe(session:) calls transcribe exactly once`() async throws {
        let mockTranscription = MockTranscriptionEngine()
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: mockTranscription,
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        _ = try await useCase.stopAndTranscribe(session: makeSession())

        let count = await mockTranscription.transcribeCallCount
        #expect(count == 1)
    }

    // MARK: - TranscriptionContext correctness

    @Test
    func `stopAndTranscribe(session:) builds TranscriptionResult with modelId from constructor`() async throws {
        // The use case must carry the injected modelId forward into the
        // TranscriptionResult it constructs — verifying modelId on the result
        // proves the constructor parameter is wired through rather than hardcoded.
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        let result = try await useCase.stopAndTranscribe(session: makeSession())

        #expect(result.transcription.modelId == ModelID("test-model"))
    }

    @Test
    func `stopAndTranscribe(session:) passes isFinalChunk: true — transcription result contains segments`(
    ) async throws {
        // isFinalChunk: true is not directly observable from outside via the mock,
        // but the call to transcribe (which requires isFinalChunk: true per the spec)
        // must produce at least one segment in the result.
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        let result = try await useCase.stopAndTranscribe(session: makeSession())

        #expect(result.transcription.segments.isEmpty == false)
    }

    // MARK: - Return value shape

    @Test
    func `stopAndTranscribe(session:) returns TranscribedRecording whose recording id matches AudioFile`() async throws {
        // MockAudioCaptureEngine.stop() returns AudioFile(id: generated, …).
        // MockStorageEngine.saveRecording() stores metadata using file.id.
        // Verifying the id proves storage.saveRecording was called with the
        // AudioFile that audioCapture.stop() returned — not some other value.
        //
        // Note: In this isolated unit test, we're not calling audioCapture.start()
        // (that's StartRecordingUseCase's job), so the MockAudioCaptureEngine
        // generates a fresh ID on stop(). In integration (StartRecordingUseCase →
        // StopAndTranscribeUseCase), INV-001 ensures AudioFile.id == RecordingSession.id.
        let mockStorage = MockStorageEngine()
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: mockStorage,
            sampleLoader: MockAudioSampleLoader(),
