import Testing
import Foundation
@testable import Business
import Domain
import AudioInfrastructure
import MLInfrastructure
import TestMocks

// MARK: - Suite

@Suite("StopAndTranscribeUseCase — Readiness Gate & Telemetry")
struct StopAndTranscribeUseCaseReadinessTests {

    // MARK: - Model readiness gate (BM-033)

    //
    // StopAndTranscribeUseCase must gate transcription on engine readiness,
    // mirroring the fix applied to StreamingTranscriptionUseCase in TASK-033.
    //
    // RED baseline: the use case currently calls transcription.transcribe()
    // without ever consulting isReady() or calling loadModel(). These three
    // tests are intentionally RED until the gate is added.

    /// AC-A: Engine starts NOT ready, loadModel succeeds → lazy-load path
    /// fires and transcribe IS called.
    ///
    /// RED: the current source never calls loadModel(). loadModelCalled stays
    /// false → #expect(loadModelCalled == true) fails.
    @Test("engine not ready: calls loadModel then transcribes (lazy-load path, AC-A)")
    func engineNotReadyCallsLoadModelThenTranscribes() async throws {
        // Precondition — engine must start not-ready (default state)
        let mockTranscription = MockTranscriptionEngine()
        let initiallyReady = await mockTranscription.isReady()
        #expect(initiallyReady == false, "Precondition: MockTranscriptionEngine must start not-ready")

        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: mockTranscription,
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        // Act — should succeed: lazy-load fires, then transcribe succeeds
        _ = try await useCase.stopAndTranscribe(session: makeSession())

        // Assert — the readiness gate must have called loadModel(), then transcribe()
        let loadCalled = await mockTranscription.loadModelCalled
        let transcribeCalled = await mockTranscription.transcribeCalled
        #expect(
            loadCalled == true,
            "use case must call loadModel() when engine is not ready (lazy-load gate)",
        )
        #expect(
            transcribeCalled == true,
            "transcribe() must be called after loadModel() succeeds",
        )
    }

    /// AC-B: Engine NOT ready and loadModel throws → transcribe is NEVER
    /// called and the error propagates to the caller.
    ///
    /// RED: the current source calls transcribe() directly. transcribeCalled
    /// becomes true (before the throw) → #expect(transcribeCalled == false) fails.
    @Test("engine not ready: loadModel throws → transcribe never called, error propagates (AC-B)")
    func engineNotReadyLoadModelThrowsAbortsPipeline() async throws {
        // Arrange — engine starts NOT ready; errorToThrow makes loadModel throw
        let mockTranscription = MockTranscriptionEngine()
        struct ModelLoadFailure: Error {}
        await mockTranscription.setErrorToThrow(ModelLoadFailure())

        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: mockTranscription,
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        // Act — execute() must propagate the loadModel error
        await #expect(throws: (any Error).self) {
            _ = try await useCase.stopAndTranscribe(session: makeSession())
        }

        // Assert — transcribe() must never have been called
        let transcribeCalled = await mockTranscription.transcribeCalled
        #expect(
            transcribeCalled == false,
            "transcribe() must not be called when loadModel throws — gate must abort the pipeline",
        )
    }

    /// AC-C: Engine already ready → loadModel is NOT called and transcribe
    /// fires immediately.
    ///
    /// Currently PASSES (the gate is absent, so loadModel is never called and
    /// transcribe is called unconditionally). Serves as a regression guard to
    /// ensure the gate's fast-path stays correct after GREEN.
    @Test("engine already ready: loadModel skipped, transcribe fires immediately (AC-C)")
    func engineAlreadyReadySkipsLoadModel() async throws {
        // Arrange — mark engine ready before execute()
        let mockTranscription = MockTranscriptionEngine()
        await mockTranscription.setReady(true)
        let isReady = await mockTranscription.isReady()
        #expect(isReady == true, "Precondition: engine must be ready before execute()")

        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: mockTranscription,
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        // Act
        _ = try await useCase.stopAndTranscribe(session: makeSession())

        // Assert — loadModel must NOT be called; transcribe must be called
        let loadCalled = await mockTranscription.loadModelCalled
        let transcribeCalled = await mockTranscription.transcribeCalled
        #expect(
            loadCalled == false,
            "loadModel() must not be called when engine is already ready",
        )
        #expect(
            transcribeCalled == true,
            "transcribe() must be called when engine is already ready",
        )
    }

    // MARK: - Inference Telemetry (Epic 3.5)

    @Test("records inference metrics to telemetry after transcription")
    func recordsInferenceTelemetry() async throws {
        let telemetry = InferenceTelemetry()
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
            telemetry: telemetry,
        )

        _ = try await useCase.stopAndTranscribe(session: makeSession())

        let recent = await telemetry.recentMetrics(limit: 1)
        #expect(recent.count == 1, "One telemetry entry must be recorded per transcription")
        #expect(recent[0].modelId == ModelID("test-model"))
        #expect(recent[0].sampleCount > 0)
        #expect(recent[0].inferenceDuration >= 0)
    }

    @Test("telemetry is optional — nil telemetry does not crash")
    func nilTelemetryDoesNotCrash() async throws {
        let useCase = StopAndTranscribeUseCase(
            audioCapture: MockAudioCaptureEngine(),
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        let result = try await useCase.stopAndTranscribe(session: makeSession())
        #expect(!result.transcription.fullText.isEmpty)
    }
}

