import Testing
import Foundation
@testable import Business
import Domain
import AudioInfrastructure
import MLInfrastructure
import TestMocks

// MARK: - Suite

@Suite("StopAndTranscribeUseCase — Crash Resilience & Recovery")
struct StopAndTranscribeUseCaseResilienceTests {

    // MARK: - WAV Preservation on Persistence Failure (F4/#193)

    @Test("WAV file is preserved on disk when saveRecording throws (retryable)")
    func wavFileIsPreservedWhenSaveRecordingThrows() async throws {
        let mockCapture = MockAudioCaptureEngine()
        let mockStorage = MockStorageEngine()

        let tempURL = URL(fileURLWithPath: NSTemporaryDirectory()).appendingPathComponent(UUID().uuidString + ".wav")
        try Data("dummy".utf8).write(to: tempURL)
        defer { try? FileManager.default.removeItem(at: tempURL) }

        let tempFile = AudioFile(
            id: RecordingID("temp-file"),
            url: tempURL,
            recordedAt: Date(),
            duration: 1.0,
            fileSize: 1024,
            configuration: AudioConfiguration(),
            sampleCount: 16000,
        )
        await mockCapture.setMockAudioFile(tempFile)

        struct TransientStorageFailure: Error {}
        await mockStorage.setErrorToThrow(TransientStorageFailure())

        let useCase = StopAndTranscribeUseCase(
            audioCapture: mockCapture,
            transcription: MockTranscriptionEngine(),
            storage: mockStorage,
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        await #expect(throws: (any Error).self) {
            _ = try await useCase.stopAndTranscribe(session: makeSession())
        }

        #expect(
            FileManager.default.fileExists(atPath: tempURL.path) == true,
            "WAV file must be preserved on disk when saveRecording throws — storage failure is retryable",
        )
    }

    @Test("forceStop deletes returned .wav file")
    func forceStopDeletesReturnedWavFile() async throws {
        let mockCapture = MockAudioCaptureEngine()

        let tempURL = URL(fileURLWithPath: NSTemporaryDirectory()).appendingPathComponent(UUID().uuidString + ".wav")
        try Data("dummy".utf8).write(to: tempURL)
        defer { try? FileManager.default.removeItem(at: tempURL) }

        let tempFile = AudioFile(
            id: RecordingID("temp-file"),
            url: tempURL,
            recordedAt: Date(),
            duration: 1.0,
            fileSize: 1024,
            configuration: AudioConfiguration(),
            sampleCount: 16000,
        )
        await mockCapture.setMockAudioFile(tempFile)

        let useCase = StopAndTranscribeUseCase(
            audioCapture: mockCapture,
            transcription: MockTranscriptionEngine(),
            storage: MockStorageEngine(),
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        await useCase.forceStop()

        #expect(
            FileManager.default.fileExists(atPath: tempURL.path) == false,
            "forceStop must delete the generated .wav file",
        )
    }

    // MARK: - Crash Resilience — WhisperKit/MLX Recovery (#116)
    //
    // These tests are intentionally RED until the GREEN phase implements:
    //   1. RecordingStatus.needsRetranscription in Domain (new enum case)
    //   2. RecordingWriteRepository.markNeedsRetranscription(id:audioURL:) protocol method
    //   3. RecordingReadRepository.listNeedsRetranscription() protocol method
    //   4. StopAndTranscribeUseCase recovery path: on transcription failure,
    //      call storage.markNeedsRetranscription() instead of propagating raw error
    //   5. RecoverPendingSessionsUseCase.callAsFunction() surfaces .needsRetranscription rows
    //   6. Audio integrity check before marking recoverable

    /// AC-1 (REQ-B1, #116): When transcription throws, the WAV file on disk
    /// must be preserved so the session can be retried. The use case must NOT
    /// delete the file on transcription failure.
    ///
    /// RED: the current use case propagates the error without ensuring the WAV
    /// is preserved; no test verifies this invariant for the transcription path.
    @Test("transcription failure preserves WAV file on disk for retry (AC-1, #116)")
    func transcriptionFailurePreservesWavFile() async throws {
        let mockCapture = MockAudioCaptureEngine()
        let mockTranscription = MockTranscriptionEngine()
        let mockStorage = MockStorageEngine()

        // Write a minimal WAV file so the TOCTOU file-handle check passes
        let wavURL = URL(fileURLWithPath: NSTemporaryDirectory())
            .appendingPathComponent(UUID().uuidString + ".wav")
        try Data("RIFF\0\0\0\0WAVEfmt ".utf8).write(to: wavURL)
        defer { try? FileManager.default.removeItem(at: wavURL) }

        let wavFile = AudioFile(
            id: RecordingID("session-crash-001"),
            url: wavURL,
            recordedAt: Date(),
            duration: 5.0,
            fileSize: Int64(wavURL.resourceValues(forKeys: [.fileSizeKey]).fileSize ?? 1024),
            configuration: AudioConfiguration(),
            sampleCount: 80000,
        )
        await mockCapture.setMockAudioFile(wavFile)

        // Make transcription throw — simulates WhisperKit/MLX crash
        struct WhisperKitCrash: Error {}
        await mockTranscription.setErrorToThrow(WhisperKitCrash())
        // Engine starts not-ready; errorToThrow fires on loadModel, skipping transcribe.
        // Force ready so the error fires on transcribe() instead.
        await mockTranscription.setReady(true)
        // Now re-set the error so transcribe() throws
        await mockTranscription.setErrorToThrow(WhisperKitCrash())

        let useCase = StopAndTranscribeUseCase(
            audioCapture: mockCapture,
            transcription: mockTranscription,
            storage: mockStorage,
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        // Act — must throw (transcription failed)
        await #expect(throws: (any Error).self) {
            _ = try await useCase.stopAndTranscribe(session: makeSession(id: RecordingID("session-crash-001")))
        }

        // Assert — WAV file must still exist on disk for retry
        #expect(
            FileManager.default.fileExists(atPath: wavURL.path) == true,
            "WAV file must be preserved on disk when transcription throws (retryable crash recovery)"
        )
    }

    /// AC-2 (REQ-B1, #116): When transcription throws, the use case must mark the
    /// stored recording as .needsRetranscription via storage.markNeedsRetranscription().
    ///
    /// RED: RecordingStatus.needsRetranscription does not exist in Domain and
    /// MockStorageEngine has no markNeedsRetranscriptionCalled tracking property.
    /// This test will fail to compile until both are added.
    @Test("transcription failure marks recording as .needsRetranscription (AC-2, #116)")
    func transcriptionFailureMarksRecordingNeedsRetranscription() async throws {
        let mockCapture = MockAudioCaptureEngine()
        let mockTranscription = MockTranscriptionEngine()
        let mockStorage = MockStorageEngine()

        let wavURL = URL(fileURLWithPath: NSTemporaryDirectory())
            .appendingPathComponent(UUID().uuidString + ".wav")
        try Data("RIFF\0\0\0\0WAVEfmt ".utf8).write(to: wavURL)
        defer { try? FileManager.default.removeItem(at: wavURL) }

        let wavFile = AudioFile(
            id: RecordingID("session-crash-002"),
            url: wavURL,
            recordedAt: Date(),
            duration: 3.0,
            fileSize: 2048,
            configuration: AudioConfiguration(),
            sampleCount: 48000,
        )
        await mockCapture.setMockAudioFile(wavFile)
        await mockTranscription.setReady(true)

        struct MLXCrash: Error {}
        await mockTranscription.setErrorToThrow(MLXCrash())

        let useCase = StopAndTranscribeUseCase(
            audioCapture: mockCapture,
            transcription: mockTranscription,
            storage: mockStorage,
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        await #expect(throws: (any Error).self) {
            _ = try await useCase.stopAndTranscribe(session: makeSession(id: RecordingID("session-crash-002")))
        }

        // RED: MockStorageEngine.markNeedsRetranscriptionCalled does not exist yet.
        // This line will produce a compile error until the GREEN phase adds:
        //   - RecordingStatus.needsRetranscription (Domain)
        //   - RecordingWriteRepository.markNeedsRetranscription(id:audioURL:) (Domain)
        //   - MockStorageEngine.markNeedsRetranscriptionCalled (TestMocks)
        let marked = await mockStorage.markNeedsRetranscriptionCalled
        #expect(
            marked == true,
            "storage.markNeedsRetranscription() must be called when transcription throws"
        )
    }

    /// AC-3 (REQ-B1, #116): RecoverPendingSessionsUseCase must surface recordings
    /// with status .needsRetranscription on next launch, not just crash-mid-capture.
    ///
    /// RED: RecordingReadRepository.listNeedsRetranscription() does not exist yet.
    /// Compile error until added.
    @Test("RecoverPendingSessionsUseCase returns .needsRetranscription sessions (AC-3, #116)")
    func recoverPendingSessionsPicksUpNeedsRetranscription() async throws {
        let mockStorage = MockStorageEngine()
        let crashedID = RecordingID("session-crashed-transcription")

        // Seed a recording that was saved but transcription crashed
        // RED: seedNeedsRetranscription(id:audioURL:) does not exist on MockStorageEngine yet.
        // This line fails to compile until MockStorageEngine gains this method.
        await mockStorage.seedNeedsRetranscription(id: crashedID, audioURL: URL(fileURLWithPath: "/tmp/dummy.wav"))

        let useCase = RecoverPendingSessionsUseCase(storage: mockStorage)
        let recovered = try await useCase()

        #expect(
            recovered.contains(crashedID),
            "RecoverPendingSessionsUseCase must surface .needsRetranscription sessions (#116)"
        )
    }

    /// AC-4 (REQ-B1, #116): Before marking a crashed session as recoverable, the
