    // MARK: - WAV Preservation on Persistence Failure (F4/#193)

    @Test("WAV file is preserved on disk when saveRecording throws (retryable)")
    func wavFileIsPreservedWhenSaveRecordingThrows() async throws {
        let mockCapture = MockAudioCaptureEngine()
        let mockStorage = MockStorageEngine()

        let tempURL = URL(fileURLWithPath: NSTemporaryDirectory()).appendingPathComponent(UUID().uuidString + ".wav")
        try Data("dummy".utf8).write(to: tempURL)
        defer { try? FileManager.default.removeItem(at: tempURL) }

        let tempFile = AudioFile(
            id: RecordingID("temp-file"),
            url: tempURL,
            recordedAt: Date(),
            duration: 1.0,
            fileSize: 1024,
            configuration: AudioConfiguration(),
            sampleCount: 16000,
        )
        await mockCapture.setMockAudioFile(tempFile)

        struct TransientStorageFailure: Error {}
        await mockStorage.setErrorToThrow(TransientStorageFailure())

        let useCase = StopAndTranscribeUseCase(
            audioCapture: mockCapture,
            transcription: MockTranscriptionEngine(),
            storage: mockStorage,
            sampleLoader: MockAudioSampleLoader(),
            modelId: ModelID("test-model"),
        )

        await #expect(throws: (any Error).self) {
            _ = try await useCase.stopAndTranscribe(session: makeSession())
        }

        #expect(
            FileManager.default.fileExists(atPath: tempURL.path) == true,
            "WAV file must be preserved on disk when saveRecording throws — storage failure is retryable",
        )
    }

    @Test("forceStop deletes returned .wav file")
    func forceStopDeletesReturnedWavFile() async throws {
        let mockCapture = MockAudioCaptureEngine()

        let tempURL = URL(fileURLWithPath: NSTemporaryDirectory()).appendingPathComponent(UUID().uuidString + ".wav")
        try Data("dummy".utf8).write(to: tempURL)
