    /// is preserved; no test verifies this invariant for the transcription path.
    @Test("transcription failure preserves WAV file on disk for retry (AC-1, #116)")
    func transcriptionFailurePreservesWavFile() async throws {
        let mockCapture = MockAudioCaptureEngine()
        let mockTranscription = MockTranscriptionEngine()
        let mockStorage = MockStorageEngine()

        // Write a minimal WAV file so the TOCTOU file-handle check passes
        let wavURL = URL(fileURLWithPath: NSTemporaryDirectory())
            .appendingPathComponent(UUID().uuidString + ".wav")
        try Data("RIFF\0\0\0\0WAVEfmt ".utf8).write(to: wavURL)
        defer { try? FileManager.default.removeItem(at: wavURL) }

        let wavFile = AudioFile(
            id: RecordingID("session-crash-001"),
            url: wavURL,
            recordedAt: Date(),
            duration: 5.0,
            fileSize: Int64(wavURL.resourceValues(forKeys: [.fileSizeKey]).fileSize ?? 1024),
            configuration: AudioConfiguration(),
            sampleCount: 80000,
        )
        await mockCapture.setMockAudioFile(wavFile)

