        //   - RecordingWriteRepository.markNeedsRetranscription(id:audioURL:) (Domain)
        //   - MockStorageEngine.markNeedsRetranscriptionCalled (TestMocks)
        let marked = await mockStorage.markNeedsRetranscriptionCalled
        #expect(
            marked == true,
            "storage.markNeedsRetranscription() must be called when transcription throws"
        )
    }

    /// AC-3 (REQ-B1, #116): RecoverPendingSessionsUseCase must surface recordings
    /// with status .needsRetranscription on next launch, not just crash-mid-capture.
